          _account_lockout_expires_at: '2024-01-03T00:00:00.000Z',
          _perishable_token_expires_at: '2024-01-04T00:00:00.000Z',
          _password_changed_at: '2024-01-05T00:00:00.000Z',
        },
        schemaWith()
      );

      expect(result._created_at).toEqual(new Date(createdAt));
      expect(result._updated_at).toEqual(new Date(updatedAt));
      expect(result.expiresAt).toEqual(new Date('2024-01-01T00:00:00.000Z'));
      expect(result._email_verify_token_expires_at).toEqual(
        new Date('2024-01-02T00:00:00.000Z')
      );
      expect(result._account_lockout_expires_at).toEqual(
        new Date('2024-01-03T00:00:00.000Z')
      );
      expect(result._perishable_token_expires_at).toEqual(
        new Date('2024-01-04T00:00:00.000Z')
      );
      expect(result._password_changed_at).toEqual(new Date('2024-01-05T00:00:00.000Z'));
      expect(result).not.toHaveProperty('createdAt');
      expect(result).not.toHaveProperty('updatedAt');
    });

    it('drops Relation fields but keeps regular fields', () => {
      const result = MongoTransform.parseObjectToMongoObjectForCreate(
        'Test',
        {
          title: 'hello',
          related: { __type: 'Relation', className: 'Other' },
        },
        schemaWith()
      );

      expect(result).toEqual({ title: 'hello' });
    });

    it('synthesizes the legacy _acl representation from _rperm and _wperm', () => {
      const result = MongoTransform.parseObjectToMongoObjectForCreate(
        'Test',
        {
          _wperm: ['role:admin', 'user-1'],
          _rperm: ['role:reader', 'user-1'],
        },
        schemaWith()
      );

      expect(result._wperm).toEqual(['role:admin', 'user-1']);
      expect(result._rperm).toEqual(['role:reader', 'user-1']);
      expect(result._acl).toEqual({
        'role:admin': { w: true },
        'user-1': { w: true, r: true },
        'role:reader': { r: true },
      });
    });

    it('passes already-transformed auth data through and rejects nested authData ids', () => {
      expect(
        MongoTransform.parseObjectToMongoObjectForCreate(
          '_User',
          { _auth_data_google: { id: 'google-id' } },
          schemaWith()
        )
      ).toEqual({ _auth_data_google: { id: 'google-id' } });

      expectParseError(
        () =>
          MongoTransform.parseObjectToMongoObjectForCreate(
            '_User',
            { 'authData.google.id': 'google-id' },
            schemaWith()
          ),
        Parse.Error.INVALID_KEY_NAME,
        'can only query on authData.google.id'
      );
    });

    it('rejects nested keys containing $ or . and unsupported function values', () => {
      expectParseError(
        () =>
          MongoTransform.parseObjectToMongoObjectForCreate(
