      });
    });

    it('rejects unsupported JavaScript values', () => {
      expect(() =>
        MongoTransform.mongoObjectToParseObject('Test', () => 'bad', schemaWith())
      ).toThrow('bad value in mongoObjectToParseObject');
    });
  });

  describe('transformPointerString', () => {
    it('converts a class$id pointer string using the schema target class', () => {
      expect(
        MongoTransform.transformPointerString(
          schemaWith({ author: { type: 'Pointer', targetClass: '_User' } }),
