'use strict';

const mongodb = require('mongodb');
const Parse = require('parse/node').Parse;
const MongoTransform = require('../../../../src/Adapters/Storage/Mongo/MongoTransform');

const schemaWith = (fields = {}) => ({ fields });
const pointer = (className = '_User', objectId = 'u1') => ({
  __type: 'Pointer',
  className,
  objectId,
});
const dateJSON = iso => ({ __type: 'Date', iso });

const expectParseError = (fn, code, message) => {
  let error;
  try {
    fn();
  } catch (caught) {
    error = caught;
  }
  expect(error).toBeInstanceOf(Parse.Error);
  expect(error.code).toBe(code);
  if (message instanceof RegExp) {
    expect(error.message).toMatch(message);
  } else if (message !== undefined) {
    expect(error.message).toBe(message);
  }
};

describe('MongoTransform', () => {
  describe('transformKey', () => {
    it.each([
      ['objectId', '_id'],
      ['createdAt', '_created_at'],
      ['updatedAt', '_updated_at'],
      ['sessionToken', '_session_token'],
      ['lastUsed', '_last_used'],
      ['timesUsed', 'times_used'],
    ])('maps built-in REST key %s to %s', (restKey, mongoKey) => {
      expect(MongoTransform.transformKey('Anything', restKey, schemaWith())).toBe(mongoKey);
    });

    it('prefixes fields represented as pointers in either schema notation', () => {
      const schema = schemaWith({
        oldStyle: { __type: 'Pointer', targetClass: 'Post' },
        newStyle: { type: 'Pointer', targetClass: 'Post' },
        plain: { type: 'String' },
      });

      expect(MongoTransform.transformKey('Post', 'oldStyle', schema)).toBe('_p_oldStyle');
      expect(MongoTransform.transformKey('Post', 'newStyle', schema)).toBe('_p_newStyle');
      expect(MongoTransform.transformKey('Post', 'plain', schema)).toBe('plain');
      expect(MongoTransform.transformKey('Post', 'unknown', schema)).toBe('unknown');
    });
  });

  describe('parseObjectToMongoObjectForCreate', () => {
    it('maps built-in fields and omits undefined values', () => {
      const result = MongoTransform.parseObjectToMongoObjectForCreate(
        'Test',
        {
          objectId: 'abc123',
          sessionToken: 'session',
          _failed_login_count: 3,
          _email_verify_token: 'verify',
          _hashed_password: 'hash',
          notStored: undefined,
        },
        schemaWith()
      );

      expect(result).toEqual({
        _id: 'abc123',
        _session_token: 'session',
        _failed_login_count: 3,
        _email_verify_token: 'verify',
        _hashed_password: 'hash',
      });
    });

    it('converts top-level Date, Bytes, GeoPoint, Polygon, File and Pointer values', () => {
      const result = MongoTransform.parseObjectToMongoObjectForCreate(
        'Test',
        {
          date: dateJSON('2020-01-02T03:04:05.000Z'),
          bytes: { __type: 'Bytes', base64: 'aGVsbG8=' },
          location: { __type: 'GeoPoint', latitude: 10, longitude: 20 },
          polygon: {
            __type: 'Polygon',
            coordinates: [
              [10, 20],
              [11, 21],
              [12, 22],
            ],
          },
          file: { __type: 'File', name: 'hello.txt' },
          owner: pointer('_User', 'user-1'),
        },
        schemaWith()
      );

      expect(result.date).toEqual(new Date('2020-01-02T03:04:05.000Z'));
      expect(result.bytes).toBeInstanceOf(mongodb.Binary);
      expect(result.bytes.buffer.toString()).toBe('hello');
      expect(result.location).toEqual([20, 10]);
      expect(result.polygon).toEqual({
        type: 'Polygon',
        coordinates: [
          [20, 10],
          [21, 11],
          [22, 12],
          [20, 10],
        ],
      });
      expect(result.file).toBe('hello.txt');
      expect(result._p_owner).toBe('_User$user-1');
    });

    it('recursively transforms arrays and nested objects while preserving nested pointer JSON', () => {
      const nestedPointer = pointer('Post', 'post-1');
      const result = MongoTransform.parseObjectToMongoObjectForCreate(
        'Test',
        {
          items: [
            nestedPointer,
            dateJSON('2020-01-01T00:00:00.000Z'),
