    });
  });

  describe('transformUpdate', () => {
    it('maps built-in, pointer, dotted, scalar, and array update values into $set', () => {
      const result = MongoTransform.transformUpdate(
        'Post',
        {
          objectId: 'post-1',
          createdAt: '2020-01-01T00:00:00.000Z',
          updatedAt: dateJSON('2020-01-02T00:00:00.000Z'),
