          'Test',
          [new Date('2020-01-01T00:00:00.000Z'), 1],
          schemaWith()
        )
      ).toEqual([{ __type: 'Date', iso: '2020-01-01T00:00:00.000Z' }, 1]);
      expect(
        MongoTransform.mongoObjectToParseObject(
          'Test',
          new Date('2020-01-01T00:00:00.000Z'),
          schemaWith()
        )
      ).toEqual({ __type: 'Date', iso: '2020-01-01T00:00:00.000Z' });
