          _updated_at: new Date('2020-01-02T00:00:00.000Z'),
          _session_token: 'session',
          _last_used: new Date('2020-01-03T00:00:00.000Z'),
          times_used: 8,
          expiresAt: new Date('2020-01-04T00:00:00.000Z'),
          _hashed_password: 'hash',
          _email_verify_token: 'verify',
          _password_changed_at: new Date('2020-01-05T00:00:00.000Z'),
        },
        schemaWith()
      );

      expect(result).toEqual({
        objectId: 'abc',
        createdAt: '2020-01-01T00:00:00.000Z',
        updatedAt: '2020-01-02T00:00:00.000Z',
        sessionToken: 'session',
        lastUsed: '2020-01-03T00:00:00.000Z',
        timesUsed: 8,
        expiresAt: { __type: 'Date', iso: '2020-01-04T00:00:00.000Z' },
