    parseClasses: {},
    relayNodeInterface,
    graphQLTypes: [],
    log: {
      warn: jest.fn(),
      error: jest.fn(),
    },
    addGraphQLType: jest.fn(type => {
      if (collide && collide(type)) {
        return undefined;
      }
      schema.graphQLTypes.push(type);
      return type;
    }),
    handleError: jest.fn(error => {
      throw error;
    }),
  };
  return schema;
};

