  it('returns no key selection when there are no selected fields', () => {
    expect(extractKeysAndInclude([])).toEqual({
      keys: undefined,
      include: undefined,
    });
  });

  it('removes __typename, converts ids, and de-duplicates selected fields', () => {
    expect(
      extractKeysAndInclude(['id', 'title', '__typename', 'author.id', 'title', 'author.id'])
    ).toEqual({
      keys: 'objectId,title,author.objectId',
      include: 'objectId,title,author.objectId',
    });
  });

  it('does not use the keys optimization when authData is selected', () => {
    expect(extractKeysAndInclude(['authData', 'username'])).toEqual({
      keys: undefined,
      include: 'authData,username',
