const originalLogger = getLogger();

function makeLogger() {
  return {
    error: jest.fn(),
    warn: jest.fn(),
    info: jest.fn(),
    debug: jest.fn(),
    verbose: jest.fn(),
    silly: jest.fn(),
  };
}

function makeConfig(overrides = {}) {
  return {
    appId: 'test-app',
    masterKey: 'master-key',
    maintenanceKey: 'maintenance-key',
    readOnlyMasterKey: 'readonly-key',
    masterKeyIps: [],
    masterKeyIpsStore: new Map(),
    maintenanceKeyIps: [],
    maintenanceKeyIpsStore: new Map(),
    readOnlyMasterKeyIps: [],
    readOnlyMasterKeyIpsStore: new Map(),
    loadKeys: jest.fn().mockResolvedValue(undefined),
    loadMasterKey: jest.fn().mockResolvedValue('master-key'),
    loggerController: makeLogger(),
    rateLimits: [],
    ...overrides,
  };
}

function makeRequest(overrides = {}) {
  const headers = {};
  for (const [key, value] of Object.entries(overrides.headers || {})) {
    headers[key.toLowerCase()] = value;
  }
  const path = overrides.path ?? '/';
  const url = overrides.url ?? path;
  const originalUrl = overrides.originalUrl ?? `/parse${url}`;
  return {
    method: 'GET',
    path,
    url,
    originalUrl,
    protocol: 'http',
    ip: '127.0.0.1',
    socket: { remoteAddress: '127.0.0.1' },
    body: undefined,
    ...overrides,
    headers,
    get: jest.fn(name => headers[String(name).toLowerCase()]),
  };
}

function makeResponse() {
  const res = {
    statusCode: 200,
    headers: {},
    body: undefined,
    headersSent: false,
    writableEnded: false,
    status: jest.fn(function (code) {
      this.statusCode = code;
      return this;
    }),
    header: jest.fn(function (name, value) {
      this.headers[name.toLowerCase()] = value;
      return this;
    }),
    set: jest.fn(function (name, value) {
      this.headers[name.toLowerCase()] = value;
      return this;
    }),
    setHeader: jest.fn(function (name, value) {
      this.headers[name.toLowerCase()] = value;
      return this;
    }),
    getHeader: jest.fn(function (name) {
      return this.headers[name.toLowerCase()];
    }),
    removeHeader: jest.fn(function (name) {
      delete this.headers[name.toLowerCase()];
    }),
    json: jest.fn(function (body) {
      this.body = body;
      return this;
    }),
    end: jest.fn(function (body) {
      this.body = body;
      this.writableEnded = true;
      return this;
    }),
    send: jest.fn(function (body) {
      this.body = body;
      this.writableEnded = true;
      return this;
    }),
    sendStatus: jest.fn(function (code) {
      this.statusCode = code;
      this.writableEnded = true;
      return this;
    }),
    once: jest.fn(),
  };
  return res;
}

