describe('checkIp', () => {
  it('allows addresses in an IPv4 subnet and rejects other addresses', () => {
    const store = new Map();
    expect(checkIp('192.168.10.25', ['192.168.10.0/24'], store)).toBe(true);
    expect(checkIp('192.168.11.25', ['192.168.10.0/24'], store)).toBe(false);
  });

  it('supports exact IPv4 and IPv6 addresses', () => {
    expect(checkIp('203.0.113.7', ['203.0.113.7'], new Map())).toBe(true);
    expect(checkIp('203.0.113.8', ['203.0.113.7'], new Map())).toBe(false);
    expect(checkIp('2001:db8::1', ['2001:db8::1'], new Map())).toBe(true);
    expect(checkIp('2001:db8::2', ['2001:db8::1'], new Map())).toBe(false);
  });

  it('supports IPv6 subnets', () => {
    expect(checkIp('2001:db8:abcd::42', ['2001:db8::/32'], new Map())).toBe(true);
    expect(checkIp('2001:db9::42', ['2001:db8::/32'], new Map())).toBe(false);
  });

  it('treats 0.0.0.0/0 as allowing all IPv4 but not IPv6', () => {
    const store = new Map();
    expect(checkIp('198.51.100.1', ['0.0.0.0/0'], store)).toBe(true);
    expect(checkIp('2001:db8::1', ['0.0.0.0/0'], store)).toBe(false);
  });

  it('treats ::/0 as allowing all IPv6 but not IPv4', () => {
    const store = new Map();
    expect(checkIp('2001:db8::1', ['::/0'], store)).toBe(true);
    expect(checkIp('198.51.100.1', ['::/0'], store)).toBe(false);
  });

  it('caches the result for an exact address on the allow list', () => {
    const store = new Map();
    expect(checkIp('198.51.100.7', ['198.51.100.7'], store)).toBe(true);
    expect(store.get('198.51.100.7')).toBe(true);
    expect(store.get('blockList')).toBeDefined();
  });

  it('reuses an already compiled block list from the store', () => {
    const store = new Map();
    checkIp('10.0.0.1', ['10.0.0.0/8'], store);
    const compiled = store.get('blockList');
    expect(checkIp('10.2.3.4', ['192.168.0.0/16'], store)).toBe(true);
    expect(store.get('blockList')).toBe(compiled);
  });
});

