describe('handleParseSession', () => {
  it('calls next without resolving auth when auth is already present', async () => {
    const getSessionAuth = jest.spyOn(auth, 'getAuthForSessionToken');
    const req = makeRequest({ path: '/classes/Test' });
    req.config = makeConfig();
    req.info = { sessionToken: 'r:token' };
    req.auth = { isMaster: false };
    const next = jest.fn();

    await handleParseSession(req, makeResponse(), next);

    expect(getSessionAuth).not.toHaveBeenCalled();
    expect(next).toHaveBeenCalledTimes(1);
  });

  it('allows GET /sessions/me without an auth object', async () => {
    const getSessionAuth = jest.spyOn(auth, 'getAuthForSessionToken');
    const req = makeRequest({ path: '/sessions/me', method: 'GET' });
    req.config = makeConfig();
    req.info = { sessionToken: 'r:token' };
    const next = jest.fn();

    await handleParseSession(req, makeResponse(), next);

    expect(getSessionAuth).not.toHaveBeenCalled();
    expect(next).toHaveBeenCalledTimes(1);
  });

  it('resolves a normal session token and assigns the resulting auth', async () => {
    const expectedAuth = { isMaster: false, user: { id: 'user-id' } };
    const getSessionAuth = jest.spyOn(auth, 'getAuthForSessionToken').mockResolvedValue(expectedAuth);
    const config = makeConfig();
    const req = makeRequest({ path: '/classes/Test' });
    req.config = config;
    req.info = { sessionToken: 'r:token', installationId: 'installation-id' };
    const next = jest.fn();

    await handleParseSession(req, makeResponse(), next);

    expect(getSessionAuth).toHaveBeenCalledWith({
      config,
      installationId: 'installation-id',
      sessionToken: 'r:token',
    });
    expect(req.auth).toBe(expectedAuth);
    expect(next).toHaveBeenCalledTimes(1);
  });

  it('resolves a legacy session token on upgradeToRevocableSession', async () => {
    const expectedAuth = { isMaster: false, user: { id: 'legacy-user' } };
    const getLegacyAuth = jest
      .spyOn(auth, 'getAuthForLegacySessionToken')
      .mockResolvedValue(expectedAuth);
    const getSessionAuth = jest.spyOn(auth, 'getAuthForSessionToken');
    const config = makeConfig();
    const req = makeRequest({ path: '/upgradeToRevocableSession' });
    req.config = config;
    req.info = { sessionToken: 'legacy-token', installationId: 'installation-id' };
    const next = jest.fn();

    await handleParseSession(req, makeResponse(), next);

    expect(getLegacyAuth).toHaveBeenCalledWith({
      config,
      installationId: 'installation-id',
      sessionToken: 'legacy-token',
    });
    expect(getSessionAuth).not.toHaveBeenCalled();
    expect(req.auth).toBe(expectedAuth);
    expect(next).toHaveBeenCalledTimes(1);
  });

  it('uses normal session auth for an already-revocable token on upgradeToRevocableSession', async () => {
    const expectedAuth = { isMaster: false };
    const getLegacyAuth = jest.spyOn(auth, 'getAuthForLegacySessionToken');
    const getSessionAuth = jest.spyOn(auth, 'getAuthForSessionToken').mockResolvedValue(expectedAuth);
    const config = makeConfig();
    const req = makeRequest({ path: '/upgradeToRevocableSession' });
    req.config = config;
    req.info = { sessionToken: 'r:already-revocable', installationId: 'installation-id' };
    const next = jest.fn();

    await handleParseSession(req, makeResponse(), next);

    expect(getLegacyAuth).not.toHaveBeenCalled();
    expect(getSessionAuth).toHaveBeenCalledTimes(1);
    expect(req.auth).toBe(expectedAuth);
  });

  it('passes a Parse.Error through to next unchanged', async () => {
    const error = new Parse.Error(Parse.Error.INVALID_SESSION_TOKEN, 'bad token');
    jest.spyOn(auth, 'getAuthForSessionToken').mockRejectedValue(error);
    const req = makeRequest({ path: '/classes/Test' });
    req.config = makeConfig();
    req.info = { sessionToken: 'bad' };
    const next = jest.fn();

    await handleParseSession(req, makeResponse(), next);

    expect(next).toHaveBeenCalledWith(error);
  });

  it('logs unexpected session auth errors and returns a sanitized unknown error', async () => {
    const internalError = new Error('database details');
    jest.spyOn(auth, 'getAuthForSessionToken').mockRejectedValue(internalError);
    const config = makeConfig();
    const req = makeRequest({ path: '/classes/Test' });
    req.config = config;
    req.info = { sessionToken: 'token' };
    const next = jest.fn();

    await handleParseSession(req, makeResponse(), next);

    expect(config.loggerController.error).toHaveBeenCalledWith(
      'error getting auth for sessionToken',
      internalError
    );
    expect(next).toHaveBeenCalledTimes(1);
    const forwarded = next.mock.calls[0][0];
    expect(forwarded).toBeInstanceOf(Parse.Error);
    expect(forwarded.code).toBe(Parse.Error.UNKNOWN_ERROR);
    expect(forwarded.message).toBe('Unknown error');
  });
});

describe('allowCrossDomain', () => {
  it('sets default CORS headers and continues for a non-OPTIONS request', () => {
    jest.spyOn(Config, 'get').mockReturnValue(undefined);
    const req = makeRequest({ path: '/classes/Test', headers: { origin: 'https://client.example' } });
    const res = makeResponse();
    const next = jest.fn();

    allowCrossDomain('test-app')(req, res, next);

    expect(Config.get).toHaveBeenCalledWith('test-app', 'http://localhost/parse');
    expect(res.header).toHaveBeenCalledWith('Access-Control-Allow-Origin', '*');
    expect(res.header).toHaveBeenCalledWith(
      'Access-Control-Allow-Methods',
      'GET,PUT,POST,DELETE,OPTIONS'
    );
    expect(res.header).toHaveBeenCalledWith('Access-Control-Allow-Headers', DEFAULT_ALLOWED_HEADERS);
    expect(res.header).toHaveBeenCalledWith(
