describe('matchesExactRoute', () => {
  it('matches an exact static route', () => {
    expect(matchesExactRoute('/login', '/login')).toBe(true);
  });

  it('matches case-insensitively and tolerates a trailing slash', () => {
    expect(matchesExactRoute('/LOGIN/', '/login')).toBe(true);
    expect(matchesExactRoute('/sessions/ME/', '/sessions/me')).toBe(true);
  });

  it('does not match route prefixes, suffixes, or different routes', () => {
    expect(matchesExactRoute('/login/extra', '/login')).toBe(false);
    expect(matchesExactRoute('/api/login', '/login')).toBe(false);
    expect(matchesExactRoute('/logout', '/login')).toBe(false);
  });

  it('returns false for non-string paths', () => {
    expect(matchesExactRoute(undefined, '/login')).toBe(false);
    expect(matchesExactRoute(null, '/login')).toBe(false);
    expect(matchesExactRoute(123, '/login')).toBe(false);
  });
});

describe('isRouteAllowed', () => {
  const config = routeAllowList => ({
    routeAllowList,
    _routeAllowListRegex: (routeAllowList || []).map(pattern => new RegExp(`^${pattern}$`)),
    mount: 'http://localhost:1337/parse',
  });

  it('allows all routes when no config or no allow list is configured', () => {
    expect(isRouteAllowed('/parse/classes/Test', null, null)).toBe(true);
    expect(isRouteAllowed('/parse/classes/Test', {}, null)).toBe(true);
    expect(isRouteAllowed('/parse/classes/Test', { routeAllowList: null }, null)).toBe(true);
  });

  it('allows master and maintenance auth regardless of the route', () => {
    const restricted = config(['users']);
    expect(isRouteAllowed('/parse/classes/Test', restricted, { isMaster: true })).toBe(true);
    expect(isRouteAllowed('/parse/classes/Test', restricted, { isMaintenance: true })).toBe(true);
  });

  it('normalizes mount, leading and trailing slashes, and query parameters', () => {
    const allowed = config(['classes/GameScore', 'users']);

    expect(isRouteAllowed('/parse/classes/GameScore', allowed, {})).toBe(true);
    expect(isRouteAllowed('/parse/classes/GameScore/?limit=10', allowed, {})).toBe(true);
    expect(isRouteAllowed('/parse/users/', allowed, {})).toBe(true);
  });

  it('matches multiple regex entries and rejects unmatched routes', () => {
    const allowed = config(['classes/Chat.*', 'functions/.*']);

    expect(isRouteAllowed('/parse/classes/ChatMessage', allowed, {})).toBe(true);
    expect(isRouteAllowed('/parse/functions/sendEmail', allowed, {})).toBe(true);
    expect(isRouteAllowed('/parse/classes/GameScore', allowed, {})).toBe(false);
  });

  it('blocks all non-master routes when the allow list is empty', () => {
    expect(isRouteAllowed('/parse/classes/Test', config([]), {})).toBe(false);
  });
});

