      error: 'db failed',
    });
    expect(config.loggerController.error).toHaveBeenCalledWith('Parse error: ', error);
    expect(next).not.toHaveBeenCalled();
  });

  it('maps Parse object-not-found errors to HTTP 404', () => {
    const error = new Parse.Error(Parse.Error.OBJECT_NOT_FOUND, 'missing');
    const req = makeRequest({ config: makeConfig() });
    const res = makeResponse();

    handleParseErrors(error, req, res, jest.fn());

    expect(res.status).toHaveBeenCalledWith(404);
    expect(res.json).toHaveBeenCalledWith({
      code: Parse.Error.OBJECT_NOT_FOUND,
      error: 'missing',
    });
  });

  it('maps other Parse errors to HTTP 400', () => {
    const error = new Parse.Error(Parse.Error.INVALID_QUERY, 'bad query');
    const req = makeRequest({ config: makeConfig() });
    const res = makeResponse();

    handleParseErrors(error, req, res, jest.fn());

    expect(res.status).toHaveBeenCalledWith(400);
    expect(res.json).toHaveBeenCalledWith({ code: Parse.Error.INVALID_QUERY, error: 'bad query' });
  });

  it('delegates Parse errors to Express when enableExpressErrorHandler is set', () => {
    const error = new Parse.Error(Parse.Error.INVALID_QUERY, 'bad query');
    const req = makeRequest({ config: makeConfig({ enableExpressErrorHandler: true }) });
    const res = makeResponse();
    const next = jest.fn();

    handleParseErrors(error, req, res, next);

    expect(next).toHaveBeenCalledWith(error);
    expect(res.status).not.toHaveBeenCalled();
  });

  it('logs USERNAME_TAKEN at the configured level', () => {
    const error = new Parse.Error(Parse.Error.USERNAME_TAKEN, 'taken');
    const config = makeConfig({ logLevels: { signupUsernameTaken: 'warn' } });
    const req = makeRequest({ config });
    const res = makeResponse();

    handleParseErrors(error, req, res, jest.fn());

    expect(config.loggerController.warn).toHaveBeenCalledWith('Parse error: ', error);
    expect(config.loggerController.error).not.toHaveBeenCalled();
  });

  it('suppresses USERNAME_TAKEN logging when configured as silent', () => {
    const error = new Parse.Error(Parse.Error.USERNAME_TAKEN, 'taken');
    const config = makeConfig({ logLevels: { signupUsernameTaken: 'silent' } });
    const req = makeRequest({ config });
    const res = makeResponse();

    handleParseErrors(error, req, res, jest.fn());

    expect(config.loggerController.warn).not.toHaveBeenCalled();
    expect(config.loggerController.error).not.toHaveBeenCalled();
    expect(res.status).toHaveBeenCalledWith(400);
  });

  it('handles regular HTTP errors and calls next outside testing', () => {
    delete process.env.TESTING;
    const error = Object.assign(new Error('teapot'), { status: 418 });
    const req = makeRequest({ config: makeConfig() });
    const res = makeResponse();
    const next = jest.fn();

    handleParseErrors(error, req, res, next);

    expect(res.status).toHaveBeenCalledWith(418);
    expect(res.json).toHaveBeenCalledWith({ error: 'teapot' });
    expect(next).toHaveBeenCalledWith(error);
  });

  it('does not call next for regular HTTP errors while testing', () => {
    process.env.TESTING = '1';
    const error = Object.assign(new Error('teapot'), { status: 418 });
    const req = makeRequest({ config: makeConfig() });
    const res = makeResponse();
    const next = jest.fn();

    handleParseErrors(error, req, res, next);

    expect(res.status).toHaveBeenCalledWith(418);
    expect(res.json).toHaveBeenCalledWith({ error: 'teapot' });
    expect(next).not.toHaveBeenCalled();
  });

  it('returns a generic HTTP 500 for unexpected errors and logs details', () => {
    process.env.TESTING = '1';
    const error = new Error('secret stack details');
    const config = makeConfig();
    const req = makeRequest({ config });
    const res = makeResponse();
    const next = jest.fn();

    handleParseErrors(error, req, res, next);

    expect(config.loggerController.error).toHaveBeenCalledWith(
      'Uncaught internal server error.',
      error,
      error.stack
    );
    expect(res.status).toHaveBeenCalledWith(500);
    expect(res.json).toHaveBeenCalledWith({
      code: Parse.Error.INTERNAL_SERVER_ERROR,
      message: 'Internal server error.',
    });
    expect(next).not.toHaveBeenCalled();
  });
});

