describe('promiseEnsureIdempotency', () => {
  const mongoAdapter = Object.create(MongoStorageAdapter.prototype);
  const postgresAdapter = Object.create(PostgresStorageAdapter.prototype);

  function idempotencyConfig(overrides = {}) {
    return makeConfig({
      database: { adapter: mongoAdapter },
      idempotencyOptions: { paths: ['classes/.*'], ttl: 60 },
      ...overrides,
    });
  }

  it.each([
    ['MongoDB', mongoAdapter],
    ['PostgreSQL', postgresAdapter],
  ])('stores the request identifier for a matching %s request', async (name, adapter) => {
    jest.useFakeTimers().setSystemTime(new Date('2024-01-02T03:04:05.000Z'));
    const config = idempotencyConfig({ database: { adapter } });
    const create = jest.spyOn(rest, 'create').mockResolvedValue({ objectId: 'idempotency-id' });
    const req = makeRequest({
      path: '/classes/GameScore/',
      headers: { 'x-parse-request-id': 'request-123' },
      config,
    });

    await promiseEnsureIdempotency(req);

    expect(create).toHaveBeenCalledTimes(1);
    expect(create.mock.calls[0][0]).toBe(config);
    expect(create.mock.calls[0][1]).toMatchObject({ isMaster: true });
    expect(create.mock.calls[0][2]).toBe('_Idempotency');
    expect(create.mock.calls[0][3]).toEqual({
      reqId: 'request-123',
      expire: {
        __type: 'Date',
        iso: '2024-01-02T03:05:05.000Z',
      },
    });
  });

  it('skips idempotency for unsupported database adapters', async () => {
    const create = jest.spyOn(rest, 'create');
    const req = makeRequest({
      path: '/classes/GameScore',
      headers: { 'x-parse-request-id': 'request-123' },
      config: idempotencyConfig({ database: { adapter: {} } }),
    });

    await expect(promiseEnsureIdempotency(req)).resolves.toBeUndefined();
    expect(create).not.toHaveBeenCalled();
  });

  it('skips idempotency when no request id is present', async () => {
    const create = jest.spyOn(rest, 'create');
    const req = makeRequest({ path: '/classes/GameScore', config: idempotencyConfig() });

    await expect(promiseEnsureIdempotency(req)).resolves.toBeUndefined();
    expect(create).not.toHaveBeenCalled();
  });

  it('skips idempotency when the request path does not match', async () => {
    const create = jest.spyOn(rest, 'create');
    const req = makeRequest({
      path: '/users',
      headers: { 'x-parse-request-id': 'request-123' },
      config: idempotencyConfig(),
    });

    await expect(promiseEnsureIdempotency(req)).resolves.toBeUndefined();
    expect(create).not.toHaveBeenCalled();
  });

  it('treats configured paths as anchored regular expressions', async () => {
    const create = jest.spyOn(rest, 'create');
    const req = makeRequest({
      path: '/classes/GameScore',
      headers: { 'x-parse-request-id': 'request-123' },
      config: idempotencyConfig({ idempotencyOptions: { paths: ['classes'], ttl: 60 } }),
    });

    await expect(promiseEnsureIdempotency(req)).resolves.toBeUndefined();
    expect(create).not.toHaveBeenCalled();
  });

  it('converts duplicate-value errors into duplicate-request errors', async () => {
    const duplicate = new Parse.Error(Parse.Error.DUPLICATE_VALUE, 'already exists');
    jest.spyOn(rest, 'create').mockRejectedValue(duplicate);
    const req = makeRequest({
      path: '/classes/GameScore',
      headers: { 'x-parse-request-id': 'request-123' },
      config: idempotencyConfig(),
    });

    await expect(promiseEnsureIdempotency(req)).rejects.toMatchObject({
      code: Parse.Error.DUPLICATE_REQUEST,
      message: 'Duplicate request',
    });
  });

  it('propagates unrelated storage errors', async () => {
    const error = new Error('database unavailable');
    jest.spyOn(rest, 'create').mockRejectedValue(error);
    const req = makeRequest({
      path: '/classes/GameScore',
      headers: { 'x-parse-request-id': 'request-123' },
      config: idempotencyConfig(),
    });

    await expect(promiseEnsureIdempotency(req)).rejects.toBe(error);
  });
});

