describe('checkIp', () => {
  test('matches IPv4 addresses and subnets', () => {
    const store = new Map();
    expect(checkIp('192.168.10.4', ['192.168.10.0/24'], store)).toBe(true);
    expect(checkIp('192.168.11.4', ['192.168.10.0/24'], store)).toBe(false);
    expect(checkIp('203.0.113.9', ['203.0.113.9'], store)).toBe(true);
  });

  test('matches IPv6 subnets', () => {
    const store = new Map();
    expect(checkIp('2001:db8::1', ['2001:db8::/32'], store)).toBe(true);
    expect(checkIp('2001:db9::1', ['2001:db8::/32'], store)).toBe(false);
  });

  test('supports catch-all entries separately for IPv4 and IPv6', () => {
    expect(checkIp('198.51.100.1', ['0.0.0.0/0'], new Map())).toBe(true);
    expect(checkIp('2001:db8::1', ['0.0.0.0/0'], new Map())).toBe(false);
    expect(checkIp('2001:db8::1', ['::/0'], new Map())).toBe(true);
    expect(checkIp('198.51.100.1', ['::/0'], new Map())).toBe(false);
  });

  test('caches an exact IP match in the supplied store', () => {
    const store = new Map();
    expect(checkIp('203.0.113.7', ['203.0.113.7'], store)).toBe(true);
    expect(store.get('203.0.113.7')).toBe(true);
    expect(checkIp('203.0.113.7', [], store)).toBe(true);
  });
});

