describe('allowCrossDomain', () => {
  test('sets default CORS headers and continues non-OPTIONS requests', () => {
    jest.spyOn(Config, 'get').mockReturnValue(undefined);
    const req = makeReq({ headers: { origin: 'https://client.example' } });
    const res = makeRes();
    const next = jest.fn();

    allowCrossDomain('test-app')(req, res, next);

    expect(res.header).toHaveBeenCalledWith('Access-Control-Allow-Origin', '*');
    expect(res.header).toHaveBeenCalledWith('Access-Control-Allow-Methods', 'GET,PUT,POST,DELETE,OPTIONS');
    expect(res.header).toHaveBeenCalledWith('Access-Control-Allow-Headers', DEFAULT_ALLOWED_HEADERS);
    expect(res.header).toHaveBeenCalledWith(
      'Access-Control-Expose-Headers',
      'X-Parse-Job-Status-Id, X-Parse-Push-Status-Id'
    );
    expect(next).toHaveBeenCalledWith();
  });

  test('reflects an allowed origin and appends configured headers', () => {
    const config = makeConfig({ allowOrigin: ['https://one.example', 'https://two.example'], allowHeaders: ['X-Custom', 'X-Other'] });
    jest.spyOn(Config, 'get').mockReturnValue(config);
    const req = makeReq({ headers: { origin: 'https://two.example' } });
    const res = makeRes();
    const next = jest.fn();

    allowCrossDomain('test-app')(req, res, next);

    expect(res.header).toHaveBeenCalledWith('Access-Control-Allow-Origin', 'https://two.example');
    expect(res.header).toHaveBeenCalledWith(
      'Access-Control-Allow-Headers',
      `${DEFAULT_ALLOWED_HEADERS}, X-Custom, X-Other`
    );
    expect(next).toHaveBeenCalled();
  });

  test('answers OPTIONS preflight without calling next', () => {
    jest.spyOn(Config, 'get').mockReturnValue(makeConfig({ allowOrigin: 'https://only.example' }));
    const req = makeReq({ method: 'OPTIONS', headers: { origin: 'https://unlisted.example' } });
    const res = makeRes();
    const next = jest.fn();

    allowCrossDomain('test-app')(req, res, next);

    expect(res.header).toHaveBeenCalledWith('Access-Control-Allow-Origin', 'https://only.example');
    expect(res.sendStatus).toHaveBeenCalledWith(200);
    expect(next).not.toHaveBeenCalled();
  });
});

