describe('matchesExactRoute', () => {
  test('matches case-insensitively and tolerates a trailing slash', () => {
    expect(matchesExactRoute('/login', '/login')).toBe(true);
    expect(matchesExactRoute('/LOGIN/', '/login')).toBe(true);
  });

  test('does not match longer paths or non-string input', () => {
    expect(matchesExactRoute('/login/extra', '/login')).toBe(false);
    expect(matchesExactRoute(undefined, '/login')).toBe(false);
    expect(matchesExactRoute(42, '/login')).toBe(false);
  });
});

describe('route allow list', () => {
  test('is inactive when no list is configured, and always allows master or maintenance auth', () => {
    expect(isRouteAllowed('/classes/Test', undefined)).toBe(true);
    expect(isRouteAllowed('/classes/Test', {})).toBe(true);
    expect(isRouteAllowed('/classes/Test', { routeAllowList: [] }, { isMaster: true })).toBe(true);
    expect(isRouteAllowed('/classes/Test', { routeAllowList: [] }, { isMaintenance: true })).toBe(true);
  });

  test('normalizes mount, query string, leading slash, and trailing slash', () => {
    const config = {
      routeAllowList: ['classes/GameScore'],
      mount: 'http://localhost:1337/parse',
      _routeAllowListRegex: [/^classes\/GameScore$/],
    };
    expect(isRouteAllowed('/parse/classes/GameScore?limit=1', config)).toBe(true);
    expect(isRouteAllowed('/parse/classes/GameScore/', config)).toBe(true);
    expect(isRouteAllowed('/parse/classes/Other', config)).toBe(false);
  });

  test('calls next for an allowed route', () => {
    const req = makeReq({ originalUrl: '/parse/classes/GameScore', config: { _routeAllowListRegex: [/^classes\/GameScore$/] } });
    const next = jest.fn();
    enforceRouteAllowList(req, makeRes(), next);
    expect(next).toHaveBeenCalledWith();
  });

  test('throws a sanitized forbidden error for a disallowed route', () => {
    const req = makeReq({
      method: 'POST',
      originalUrl: '/parse/classes/Secret?x=1',
      config: {
        routeAllowList: [],
        mount: 'http://localhost:1337/parse',
        _routeAllowListRegex: [],
        enableSanitizedErrorResponse: false,
      },
    });
    expect(() => enforceRouteAllowList(req, makeRes(), jest.fn())).toThrow(Parse.Error);
    try {
      enforceRouteAllowList(req, makeRes(), jest.fn());
    } catch (error) {
      expect(error.code).toBe(Parse.Error.OPERATION_FORBIDDEN);
      expect(error.message).toBe('Route not allowed by routeAllowList: POST classes/Secret');
    }
  });
});

describe('handleParseErrors', () => {
  test('maps Parse errors to HTTP statuses and logs them', () => {
    const config = makeConfig();
    const res = makeRes();
    handleParseErrors(new Parse.Error(Parse.Error.OBJECT_NOT_FOUND, 'missing'), makeReq({ config }), res, jest.fn());
    expect(res.statusCode).toBe(404);
    expect(res.body).toEqual({ code: Parse.Error.OBJECT_NOT_FOUND, error: 'missing' });
    expect(config.loggerController.error).toHaveBeenCalled();
  });

  test('forwards errors when enableExpressErrorHandler is set', () => {
    const config = makeConfig({ enableExpressErrorHandler: true });
    const error = new Parse.Error(Parse.Error.INTERNAL_SERVER_ERROR, 'boom');
    const next = jest.fn();
    handleParseErrors(error, makeReq({ config }), makeRes(), next);
    expect(next).toHaveBeenCalledWith(error);
  });

  test('honors silent username-taken logging', () => {
    const config = makeConfig({ logLevels: { signupUsernameTaken: 'silent' } });
    const res = makeRes();
    handleParseErrors(new Parse.Error(Parse.Error.USERNAME_TAKEN, 'taken'), makeReq({ config }), res, jest.fn());
    expect(res.statusCode).toBe(400);
    expect(config.loggerController.error).not.toHaveBeenCalled();
    expect(config.loggerController.warn).not.toHaveBeenCalled();
  });

  test('uses the configured username-taken logger level', () => {
    const config = makeConfig({ logLevels: { signupUsernameTaken: 'warn' } });
    const error = new Parse.Error(Parse.Error.USERNAME_TAKEN, 'taken');
    handleParseErrors(error, makeReq({ config }), makeRes(), jest.fn());
    expect(config.loggerController.warn).toHaveBeenCalledWith('Parse error: ', error);
    expect(config.loggerController.error).not.toHaveBeenCalled();
  });

  test('returns status-bearing errors and only invokes next outside testing', () => {
    const config = makeConfig();
    const error = Object.assign(new Error('teapot'), { status: 418 });
    const next = jest.fn();
    process.env.TESTING = '1';
    handleParseErrors(error, makeReq({ config }), makeRes(), next);
    expect(next).not.toHaveBeenCalled();
    process.env.TESTING = '';
    const res = makeRes();
    handleParseErrors(error, makeReq({ config }), res, next);
    expect(res.statusCode).toBe(418);
    expect(res.body).toEqual({ error: 'teapot' });
    expect(next).toHaveBeenCalledWith(error);
  });

  test('returns an internal server error for unknown errors', () => {
    const config = makeConfig();
    const error = new Error('secret internal detail');
    const res = makeRes();
    process.env.TESTING = '1';
    handleParseErrors(error, makeReq({ config }), res, jest.fn());
    expect(res.statusCode).toBe(500);
    expect(res.body).toEqual({ code: Parse.Error.INTERNAL_SERVER_ERROR, message: 'Internal server error.' });
    expect(config.loggerController.error).toHaveBeenCalledWith('Uncaught internal server error.', error, error.stack);
  });
});

