    expect(entry.path.regexp.test('/login')).toBe(true);
    expect(entry.path.regexp.test('/login/extra')).toBe(false);
    expect(entry.requestCount).toBe(3);
    expect(entry.errorResponseMessage).toBe('Too many requests.');
    expect(entry.cloud).toBeUndefined();
    expect(typeof entry.handler).toBe('function');
    expect(Config.put).toHaveBeenCalledWith(config);
  });

  test('rejects unknown rate limit options', () => {
    const config = makeConfig();
    jest.spyOn(Config, 'put').mockImplementation(value => value);
    expect(() => addRateLimit({ requestPath: '/login', unsupported: true }, config)).toThrow(
      'Invalid rate limit option "unsupported"'
    );
    expect(config.rateLimits).toHaveLength(0);
  });

  test('enforces the configured request threshold', async () => {
    const config = makeConfig({ rateLimits: undefined });
    jest.spyOn(Config, 'put').mockImplementation(value => value);
    addRateLimit({ requestPath: '/login', requestCount: 1, requestTimeWindow: 60000 }, config);
    const entry = config.rateLimits[0];
    const makeRateReq = () => {
      const request = makeReq({
        path: '/login',
        url: '/login',
        originalUrl: '/login',
        ip: '203.0.113.5',
        config,
        info: { sessionToken: 'r:one' },
        auth: { isMaster: false },
      });
      request.app = { get: () => false };
      return request;
    };
    const makeRateRes = () => {
      const response = makeRes();
      response.setHeader = jest.fn();
      response.getHeader = jest.fn();
      response.removeHeader = jest.fn();
      response.once = jest.fn();
      response.writableEnded = false;
      return response;
    };

    const firstNext = jest.fn();
    await entry.handler(makeRateReq(), makeRateRes(), firstNext);
    expect(firstNext).toHaveBeenCalledWith();

    await expect(entry.handler(makeRateReq(), makeRateRes(), jest.fn())).rejects.toMatchObject({
      code: Parse.Error.CONNECTION_FAILED,
      message: 'Too many requests.',
    });
  });
});

describe('promiseEnsureIdempotency', () => {
  test('does nothing for unsupported adapters', async () => {
    const create = jest.spyOn(rest, 'create');
    const req = {
      config: { database: { adapter: {} }, idempotencyOptions: { paths: ['.*'], ttl: 10 } },
      headers: { 'x-parse-request-id': 'request-1' },
      path: '/classes/Test',
    };
    await expect(promiseEnsureIdempotency(req)).resolves.toBeUndefined();
    expect(create).not.toHaveBeenCalled();
  });

  test('does nothing when the request has no request id', async () => {
    const create = jest.spyOn(rest, 'create');
    const req = {
      config: { database: { adapter: Object.create(MongoStorageAdapter.prototype) }, idempotencyOptions: { paths: ['.*'], ttl: 10 } },
      headers: {},
      path: '/classes/Test',
    };
    await expect(promiseEnsureIdempotency(req)).resolves.toBeUndefined();
    expect(create).not.toHaveBeenCalled();
  });

  test('does nothing when the path is not configured for idempotency', async () => {
    const create = jest.spyOn(rest, 'create');
    const req = {
      config: { database: { adapter: Object.create(PostgresStorageAdapter.prototype) }, idempotencyOptions: { paths: ['functions/.*'], ttl: 10 } },
      headers: { 'x-parse-request-id': 'request-1' },
      path: '/classes/Test',
    };
    await expect(promiseEnsureIdempotency(req)).resolves.toBeUndefined();
    expect(create).not.toHaveBeenCalled();
  });

  test('stores an idempotency record for a matching request with a deterministic expiry', async () => {
    jest.useFakeTimers().setSystemTime(new Date('2024-01-02T03:04:05.000Z'));
    const create = jest.spyOn(rest, 'create').mockResolvedValue({ objectId: 'idem-1' });
    const config = {
      database: { adapter: Object.create(MongoStorageAdapter.prototype) },
      idempotencyOptions: { paths: ['classes/.*'], ttl: 300 },
    };
    const req = {
      config,
      headers: { 'x-parse-request-id': 'request-1' },
      path: '/classes/Test/',
    };

    await expect(promiseEnsureIdempotency(req)).resolves.toEqual({ objectId: 'idem-1' });
    expect(create).toHaveBeenCalledTimes(1);
    const [passedConfig, passedAuth, className, object] = create.mock.calls[0];
    expect(passedConfig).toBe(config);
    expect(passedAuth.isMaster).toBe(true);
    expect(className).toBe('_Idempotency');
    expect(object).toEqual({
      reqId: 'request-1',
      expire: { __type: 'Date', iso: '2024-01-02T03:09:05.000Z' },
    });
    jest.useRealTimers();
  });

  test('translates a duplicate record into a duplicate request error', async () => {
    jest.spyOn(rest, 'create').mockRejectedValue(new Parse.Error(Parse.Error.DUPLICATE_VALUE, 'duplicate'));
    const req = {
      config: {
        database: { adapter: Object.create(MongoStorageAdapter.prototype) },
        idempotencyOptions: { paths: ['classes/.*'], ttl: 300 },
      },
      headers: { 'x-parse-request-id': 'request-1' },
      path: '/classes/Test',
    };

    await expect(promiseEnsureIdempotency(req)).rejects.toMatchObject({
      code: Parse.Error.DUPLICATE_REQUEST,
      message: 'Duplicate request',
    });
  });

  test('propagates other storage errors', async () => {
    const error = new Parse.Error(Parse.Error.INTERNAL_SERVER_ERROR, 'database failed');
    jest.spyOn(rest, 'create').mockRejectedValue(error);
    const req = {
      config: {
        database: { adapter: Object.create(PostgresStorageAdapter.prototype) },
        idempotencyOptions: { paths: ['classes/.*'], ttl: 300 },
      },
      headers: { 'x-parse-request-id': 'request-1' },
      path: '/classes/Test',
    };

    await expect(promiseEnsureIdempotency(req)).rejects.toBe(error);
  });
});

