describe('UsersRouter.handleLogIn', () => {
  function loginRequest(overrides = {}) {
    return createRequest({ body: { username: 'alice', password: 'secret' }, ...overrides });
  }

  it('logs in, creates a session and returns the re-fetched user', async () => {
    const req = loginRequest({ auth: { isMaster: true } });
    const user = { objectId: 'u1', username: 'alice', password: 'hashed' };
    setupSuccessfulAuthentication(req.config, user);
    rest.get.mockResolvedValue({ results: [{ objectId: 'u1', username: 'alice' }] });

    const result = await router.handleLogIn(req);

    expect(Auth.checkIfUserHasProvidedConfiguredProvidersForLogin).toHaveBeenCalledWith(
