      undefined,
      user.authData,
      req.config
    );
    expect(req.config.filesController.expandFilesInObject).toHaveBeenCalled();
    expect(RestWrite.createSession).toHaveBeenCalledWith(
      req.config,
      expect.objectContaining({ userId: 'u1', installationId: 'install-id' })
    );
    expect(maybeRunTrigger.mock.calls.map(call => call[0])).toEqual([
      Types.beforeLogin,
      Types.afterLogin,
    ]);
    expect(result.response).toEqual({ objectId: 'u1', username: 'alice', sessionToken: 'r:new-token' });
  });

  it('returns only the identity when a non-master re-fetch is denied', async () => {
    const req = loginRequest();
    const user = {
      objectId: 'u1',
      username: 'alice',
      password: 'hashed',
      authData: { google: { id: 'g1', secret: 'mfa' } },
    };
    setupSuccessfulAuthentication(req.config, user);
    rest.get.mockRejectedValue(new Error('CLP denied'));

    const result = await router.handleLogIn(req);
    expect(result.response).toEqual({ objectId: 'u1', sessionToken: 'r:new-token' });
    expect(result.response.username).toBeUndefined();
    expect(result.response.authData).toBeUndefined();
  });

  it('returns the full row when a master re-fetch is empty', async () => {
    const req = loginRequest({ auth: { isMaster: true } });
    const user = { objectId: 'u1', username: 'alice', password: 'hashed' };
    setupSuccessfulAuthentication(req.config, user);
    rest.get.mockResolvedValue({ results: [] });

    const result = await router.handleLogIn(req);
    expect(result.response).toEqual({
      objectId: 'u1',
      username: 'alice',
      sessionToken: 'r:new-token',
    });
    expect(result.response.password).toBeUndefined();
  });

  it('rejects an auth identity that is linked to another user', async () => {
    const req = loginRequest({ auth: { isMaster: true } });
    req.body.authData = { google: { id: 'g1' } };
    setupSuccessfulAuthentication(req.config, { objectId: 'u1', username: 'alice', password: 'hashed' });
    Auth.findUsersWithAuthData.mockResolvedValue([{ objectId: 'u2' }]);

    await expect(router.handleLogIn(req)).rejects.toMatchObject({
      code: Parse.Error.ACCOUNT_ALREADY_LINKED,
      message: 'this auth is already used',
    });
    expect(Auth.handleAuthDataValidation).not.toHaveBeenCalled();
  });

  it('updates validated auth data with an optimistic lock and returns the response', async () => {
    const req = loginRequest({ auth: { isMaster: true } });
    req.body.authData = { google: { id: 'g1', token: 'new' } };
    const user = {
      objectId: 'u1',
      username: 'alice',
      password: 'hashed',
      authData: { google: { id: 'g1', token: 'old' } },
    };
    setupSuccessfulAuthentication(req.config, user);
    Auth.findUsersWithAuthData.mockResolvedValue([{ objectId: 'u1' }]);
    Auth.handleAuthDataValidation.mockResolvedValue({
      authDataResponse: { linked: true },
      authData: { google: { id: 'g1', token: 'new' } },
    });
    rest.get.mockResolvedValue({ results: [{ objectId: 'u1', username: 'alice' }] });

    const result = await router.handleLogIn(req);
    expect(req.config.database.update).toHaveBeenCalledWith(
      '_User',
      { objectId: 'u1', 'authData.google.token': 'old' },
      { authData: { google: { id: 'g1', token: 'new' } } },
      {}
    );
    expect(result.response.authDataResponse).toEqual({ linked: true });
  });

  it('translates an auth data update conflict into SCRIPT_FAILED', async () => {
    const req = loginRequest({ auth: { isMaster: true } });
    req.body.authData = { google: { id: 'g1', token: 'new' } };
    setupSuccessfulAuthentication(req.config, {
      objectId: 'u1',
      username: 'alice',
      password: 'hashed',
      authData: { google: { id: 'g1', token: 'old' } },
    });
    Auth.findUsersWithAuthData.mockResolvedValue([{ objectId: 'u1' }]);
    Auth.handleAuthDataValidation.mockResolvedValue({
      authData: { google: { id: 'g1', token: 'new' } },
    });
    req.config.database.update.mockRejectedValue(
      new Parse.Error(Parse.Error.OBJECT_NOT_FOUND, 'not found')
    );

    await expect(router.handleLogIn(req)).rejects.toMatchObject({
      code: Parse.Error.SCRIPT_FAILED,
      message: 'Invalid auth data',
    });
  });

  it('rejects expired passwords', async () => {
    const req = loginRequest({ auth: { isMaster: true } });
    req.config.passwordPolicy = { maxPasswordAge: 1 };
    setupSuccessfulAuthentication(req.config, {
      objectId: 'u1',
      username: 'alice',
      password: 'hashed',
      _password_changed_at: {
        __type: 'Date',
        iso: new Date(Date.now() - 2 * 86400000).toISOString(),
      },
    });

    await expect(router.handleLogIn(req)).rejects.toMatchObject({
      code: Parse.Error.OBJECT_NOT_FOUND,
      message: 'Your password has expired. Please reset your password.',
    });
  });

  it('does not create a session when the beforeLogin trigger fails', async () => {
    const req = loginRequest({ auth: { isMaster: true } });
    setupSuccessfulAuthentication(req.config, { objectId: 'u1', username: 'alice', password: 'hashed' });
    maybeRunTrigger.mockRejectedValue(new Parse.Error(Parse.Error.OTHER_CAUSE, 'blocked'));

    await expect(router.handleLogIn(req)).rejects.toMatchObject({ code: Parse.Error.OTHER_CAUSE });
    expect(RestWrite.createSession).not.toHaveBeenCalled();
  });
});

