    expect(result.response).toEqual({ objectId: 'user-1', username: 'alice' });
    expect(result.response).not.toHaveProperty('password');
    expect(rest.get).toHaveBeenCalledWith(
      req.config,
      req.auth,
      '_User',
      'user-1',
      {},
      req.info.context
    );
  });
});

describe('UsersRouter.handleLogIn', () => {
  it('creates a session, runs login triggers, expands files, and returns the re-fetched user', async () => {
    const req = makeReq({ body: { username: 'alice', password: 'secret' } });
    const dbUser = makeUser();
    req.config.database.find.mockResolvedValue([dbUser]);
    passwordCrypto.compare.mockResolvedValue(true);
    rest.get.mockResolvedValue({ results: [{ objectId: 'user-1', username: 'alice' }] });
    const session = makeSession();
    RestWrite.createSession.mockReturnValue(session);

    const result = await new UsersRouter().handleLogIn(req);

    expect(req.config.filesController.expandFilesInObject).toHaveBeenCalledWith(req.config, expect.any(Object));
    expect(RestWrite.createSession).toHaveBeenCalledWith(req.config, {
      userId: 'user-1',
      createdWith: { action: 'login', provider: undefined },
      installationId: 'install',
    });
    expect(session.createSession).toHaveBeenCalledTimes(1);
    expect(maybeRunTrigger).toHaveBeenNthCalledWith(
      1,
      Types.beforeLogin,
      req.auth,
      expect.anything(),
      null,
      req.config,
      req.info.context
    );
    expect(maybeRunTrigger).toHaveBeenNthCalledWith(
      2,
      Types.afterLogin,
      expect.objectContaining({ user: expect.anything() }),
      expect.anything(),
      null,
      req.config,
      req.info.context
    );
    expect(result.response).toEqual({
      objectId: 'user-1',
      username: 'alice',
      sessionToken: 'r:new-session',
    });
  });

  it('returns only identity and the new session token when a non-master re-fetch is denied', async () => {
    const req = makeReq({ body: { username: 'alice', password: 'secret' } });
    req.config.database.find.mockResolvedValue([makeUser()]);
    passwordCrypto.compare.mockResolvedValue(true);
    rest.get.mockResolvedValue({ results: [] });

    const result = await new UsersRouter().handleLogIn(req);

    expect(result.response).toEqual({ objectId: 'user-1', sessionToken: 'r:new-session' });
  });

  it('returns the full sanitized row to master callers when the re-fetch is empty', async () => {
    const req = makeReq({ body: { username: 'alice', password: 'secret' }, auth: { isMaster: true } });
    req.config.database.find.mockResolvedValue([makeUser({ _hidden: 1 })]);
    passwordCrypto.compare.mockResolvedValue(true);
    rest.get.mockResolvedValue({ results: [] });

    const result = await new UsersRouter().handleLogIn(req);

    expect(result.response.objectId).toBe('user-1');
    expect(result.response.username).toBe('alice');
    expect(result.response).not.toHaveProperty('password');
    expect(result.response).not.toHaveProperty('_hidden');
  });

  it('rejects an authData identity that is already linked to a different user', async () => {
    const req = makeReq({
      body: { username: 'alice', password: 'secret', authData: { facebook: { id: 'fb-1' } } },
    });
    req.config.database.find.mockResolvedValue([makeUser()]);
    passwordCrypto.compare.mockResolvedValue(true);
    Auth.findUsersWithAuthData.mockResolvedValue([{ objectId: 'someone-else' }]);

    await expect(new UsersRouter().handleLogIn(req)).rejects.toMatchObject({
      code: Parse.Error.ACCOUNT_ALREADY_LINKED,
      message: 'this auth is already used',
    });
    expect(Auth.handleAuthDataValidation).not.toHaveBeenCalled();
  });

  it('persists validated authData with an optimistic lock and returns authDataResponse', async () => {
    const req = makeReq({
      body: { username: 'alice', password: 'secret', authData: { facebook: { id: 'fb-1', token: 'new' } } },
      auth: { isMaster: true },
    });
    const dbUser = makeUser({ authData: { facebook: { id: 'fb-1', token: 'old' } } });
    req.config.database.find.mockResolvedValue([dbUser]);
    passwordCrypto.compare.mockResolvedValue(true);
    Auth.findUsersWithAuthData.mockResolvedValue([{ objectId: 'user-1' }]);
    Auth.handleAuthDataValidation.mockResolvedValue({
      authData: { facebook: { id: 'fb-1', token: 'new' } },
      authDataResponse: { linked: true },
    });
    req.config.database.update.mockResolvedValue({});
    rest.get.mockResolvedValue({ results: [{ objectId: 'user-1', username: 'alice' }] });

    const result = await new UsersRouter().handleLogIn(req);

    expect(req.config.database.update).toHaveBeenCalledWith(
      '_User',
      expect.objectContaining({ objectId: 'user-1', 'authData.facebook.token': 'old' }),
      { authData: { facebook: { id: 'fb-1', token: 'new' } } },
      {}
    );
    expect(result.response.authDataResponse).toEqual({ linked: true });
  });

  it('maps an optimistic-lock miss during authData persistence to a script failure', async () => {
    const req = makeReq({
      body: { username: 'alice', password: 'secret', authData: { facebook: { id: 'fb-1', token: 'new' } } },
      auth: { isMaster: true },
    });
    req.config.database.find.mockResolvedValue([makeUser({ authData: { facebook: { id: 'fb-1', token: 'old' } } })]);
    passwordCrypto.compare.mockResolvedValue(true);
    Auth.findUsersWithAuthData.mockResolvedValue([{ objectId: 'user-1' }]);
    Auth.handleAuthDataValidation.mockResolvedValue({
      authData: { facebook: { id: 'fb-1', token: 'new' } },
      authDataResponse: {},
    });
    req.config.database.update.mockRejectedValue(new Parse.Error(Parse.Error.OBJECT_NOT_FOUND, 'not found'));

    await expect(new UsersRouter().handleLogIn(req)).rejects.toMatchObject({
      code: Parse.Error.SCRIPT_FAILED,
      message: 'Invalid auth data',
    });
  });

  it('rejects an expired password', async () => {
    const req = makeReq({ body: { username: 'alice', password: 'secret' } });
    req.config.passwordPolicy = { maxPasswordAge: 30 };
    req.config.database.find.mockResolvedValue([
      makeUser({ _password_changed_at: { __type: 'Date', iso: '2000-01-01T00:00:00.000Z' } }),
    ]);
    passwordCrypto.compare.mockResolvedValue(true);

    await expect(new UsersRouter().handleLogIn(req)).rejects.toMatchObject({
      code: Parse.Error.OBJECT_NOT_FOUND,
      message: 'Your password has expired. Please reset your password.',
    });
  });

  it('starts password expiry tracking for users without a password change timestamp', async () => {
    const req = makeReq({ body: { username: 'alice', password: 'secret' } });
    req.config.passwordPolicy = { maxPasswordAge: 30 };
    req.config.database.find.mockResolvedValue([makeUser()]);
    req.config.database.update.mockResolvedValue({});
    passwordCrypto.compare.mockResolvedValue(true);
    rest.get.mockResolvedValue({ results: [{ objectId: 'user-1', username: 'alice' }] });

    await new UsersRouter().handleLogIn(req);

    expect(req.config.database.update).toHaveBeenCalledWith(
      '_User',
      { username: 'alice' },
      { _password_changed_at: expect.anything() }
    );
  });
});

describe('UsersRouter.handleLogInAs', () => {
  it('rejects non-master callers', async () => {
    const req = makeReq({ body: { userId: 'user-1' } });

    await expect(new UsersRouter().handleLogInAs(req)).rejects.toMatchObject({
      code: Parse.Error.OPERATION_FORBIDDEN,
      message: 'master key is required',
    });
  });

  it('rejects read-only master keys', async () => {
    const req = makeReq({ body: { userId: 'user-1' }, auth: { isMaster: true, isReadOnly: true } });

    await expect(new UsersRouter().handleLogInAs(req)).rejects.toMatchObject({
      code: Parse.Error.OPERATION_FORBIDDEN,
      message: "read-only masterKey isn't allowed to login as another user.",
    });
  });

  it('requires a userId', async () => {
    const req = makeReq({ auth: { isMaster: true } });

    await expect(new UsersRouter().handleLogInAs(req)).rejects.toMatchObject({
      code: Parse.Error.INVALID_VALUE,
      message: 'userId must not be empty, null, or undefined',
    });
    expect(req.config.database.find).not.toHaveBeenCalled();
  });

  it('rejects when the target user does not exist', async () => {
    const req = makeReq({ body: { userId: 'missing' }, auth: { isMaster: true } });
    req.config.database.find.mockResolvedValue([]);

    await expect(new UsersRouter().handleLogInAs(req)).rejects.toMatchObject({
      code: Parse.Error.OBJECT_NOT_FOUND,
      message: 'user not found',
    });
  });

  it('accepts userId from the query string and creates a sanitized session', async () => {
    const req = makeReq({ body: {}, query: { userId: 'user-1' }, auth: { isMaster: true } });
    req.config.database.find.mockResolvedValue([
      makeUser({ authData: { facebook: null, google: { id: 'g1' } } }),
    ]);
    const session = makeSession();
    RestWrite.createSession.mockReturnValue(session);

    const result = await new UsersRouter().handleLogInAs(req);

    expect(req.config.database.find).toHaveBeenCalledWith('_User', { objectId: 'user-1' });
    expect(RestWrite.createSession).toHaveBeenCalledWith(req.config, {
      userId: 'user-1',
      createdWith: { action: 'login', provider: 'masterkey' },
      installationId: 'install',
    });
    expect(session.createSession).toHaveBeenCalledTimes(1);
    expect(result.response).toMatchObject({
      objectId: 'user-1',
      username: 'alice',
      sessionToken: 'r:new-session',
      authData: { google: { id: 'g1' } },
    });
    expect(result.response).not.toHaveProperty('password');
  });
});

